import { getAddressEncoder, getBase58Decoder, } from "@solana/kit";
import { fetchMaybeEscrowAccount, fetchMaybePendingSettlement, fetchMaybeSessionKey, getEscrowAccountDecoder, getEscrowAccountDiscriminatorBytes, getPendingSettlementDecoder, getPendingSettlementDiscriminatorBytes, FLEX_PROGRAM_ADDRESS, } from "./generated/index.js";
function toBase58Filter(bytes) {
    return getBase58Decoder().decode(bytes);
}
function decodeBase64AccountData(data) {
    const binary = atob(data[0]);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) {
        bytes[i] = binary.charCodeAt(i);
    }
    return bytes;
}
function convertEscrowAccount(raw) {
    return {
        version: raw.version,
        owner: raw.owner,
        facilitator: raw.facilitator,
        index: raw.index,
        pendingCount: raw.pendingCount,
        mintCount: raw.mintCount,
        refundTimeoutSlots: raw.refundTimeoutSlots,
        deadmanTimeoutSlots: raw.deadmanTimeoutSlots,
        lastActivitySlot: raw.lastActivitySlot,
        maxSessionKeys: raw.maxSessionKeys,
        sessionKeyCount: raw.sessionKeyCount,
        bump: raw.bump,
    };
}
function convertSessionKey(raw) {
    return {
        version: raw.version,
        escrow: raw.escrow,
        key: raw.key,
        createdAtSlot: raw.createdAtSlot,
        expiresAtSlot: raw.expiresAtSlot.__option === "Some" ? raw.expiresAtSlot.value : null,
        active: raw.active,
        revokedAtSlot: raw.revokedAtSlot.__option === "Some" ? raw.revokedAtSlot.value : null,
        revocationGracePeriodSlots: raw.revocationGracePeriodSlots,
        bump: raw.bump,
    };
}
function convertPendingSettlement(raw) {
    return {
        version: raw.version,
        escrow: raw.escrow,
        mint: raw.mint,
        amount: raw.amount,
        originalAmount: raw.originalAmount,
        maxAmount: raw.maxAmount,
        authorizationId: raw.authorizationId,
        expiresAtSlot: raw.expiresAtSlot,
        submittedAtSlot: raw.submittedAtSlot,
        sessionKey: raw.sessionKey,
        splitCount: raw.splitCount,
        splits: raw.splits.slice(0, raw.splitCount).map((s) => ({
            recipient: s.recipient,
            bps: s.bps,
        })),
        bump: raw.bump,
    };
}
/**
 * Fetches a single escrow account by address.
 *
 * @param rpc - Solana RPC client
 * @param addr - On-chain address of the escrow PDA
 * @returns The decoded account data, or `null` if it does not exist
 */
export async function fetchEscrowAccount(rpc, addr) {
    const result = await fetchMaybeEscrowAccount(rpc, addr);
    if (!result.exists)
        return null;
    return convertEscrowAccount(result.data);
}
/**
 * Fetches a single session key account by address.
 *
 * @param rpc - Solana RPC client
 * @param addr - On-chain address of the session key PDA
 * @returns The decoded session key data, or `null` if it does not exist
 */
export async function fetchSessionKey(rpc, addr) {
    const result = await fetchMaybeSessionKey(rpc, addr);
    if (!result.exists)
        return null;
    return convertSessionKey(result.data);
}
/**
 * Fetches a single pending settlement account by address.
 *
 * @param rpc - Solana RPC client
 * @param addr - On-chain address of the pending settlement PDA
 * @returns The decoded settlement data, or `null` if it does not exist
 */
export async function fetchPendingSettlement(rpc, addr) {
    const result = await fetchMaybePendingSettlement(rpc, addr);
    if (!result.exists)
        return null;
    return convertPendingSettlement(result.data);
}
/**
 * Finds all escrow accounts owned by a given wallet using
 * `getProgramAccounts` with a discriminator + owner filter.
 *
 * @param rpc - Solana RPC client
 * @param owner - Wallet address of the escrow owner
 * @returns Array of escrow addresses and their decoded data
 */
export async function findEscrowsByOwner(rpc, owner) {
    const addressEncoder = getAddressEncoder();
    const results = await rpc
        .getProgramAccounts(FLEX_PROGRAM_ADDRESS, {
        encoding: "base64",
        filters: [
            {
                memcmp: {
                    offset: 0n,
                    bytes: toBase58Filter(new Uint8Array(getEscrowAccountDiscriminatorBytes())),
                    encoding: "base58",
                },
            },
            {
                memcmp: {
                    offset: 9n,
                    bytes: toBase58Filter(new Uint8Array(addressEncoder.encode(owner))),
                    encoding: "base58",
                },
            },
        ],
    })
        .send();
    const escrowDecoder = getEscrowAccountDecoder();
    return results.map((r) => ({
        address: r.pubkey,
        account: convertEscrowAccount(escrowDecoder.decode(decodeBase64AccountData(r.account.data))),
    }));
}
/**
 * Finds all escrow accounts managed by a given facilitator using
 * `getProgramAccounts` with a discriminator + facilitator filter.
 *
 * @param rpc - Solana RPC client
 * @param facilitator - Address of the facilitator
 * @returns Array of escrow addresses and their decoded data
 */
export async function findEscrowsByFacilitator(rpc, facilitator) {
    const addressEncoder = getAddressEncoder();
    const results = await rpc
        .getProgramAccounts(FLEX_PROGRAM_ADDRESS, {
        encoding: "base64",
        filters: [
            {
                memcmp: {
                    offset: 0n,
                    bytes: toBase58Filter(new Uint8Array(getEscrowAccountDiscriminatorBytes())),
                    encoding: "base58",
                },
            },
            {
                memcmp: {
                    offset: 41n,
                    bytes: toBase58Filter(new Uint8Array(addressEncoder.encode(facilitator))),
                    encoding: "base58",
                },
            },
        ],
    })
        .send();
    const escrowDecoder = getEscrowAccountDecoder();
    return results.map((r) => ({
        address: r.pubkey,
        account: convertEscrowAccount(escrowDecoder.decode(decodeBase64AccountData(r.account.data))),
    }));
}
/**
 * Finds all pending settlement accounts belonging to an escrow using
 * `getProgramAccounts` with a discriminator + escrow filter.
 *
 * @param rpc - Solana RPC client
 * @param escrow - Address of the parent escrow PDA
 * @returns Array of pending settlement addresses and their decoded data
 */
export async function findPendingSettlementsByEscrow(rpc, escrow) {
    const addressEncoder = getAddressEncoder();
    const results = await rpc
        .getProgramAccounts(FLEX_PROGRAM_ADDRESS, {
        encoding: "base64",
        filters: [
            {
                memcmp: {
                    offset: 0n,
                    bytes: toBase58Filter(new Uint8Array(getPendingSettlementDiscriminatorBytes())),
                    encoding: "base58",
                },
            },
            {
                memcmp: {
                    offset: 9n,
                    bytes: toBase58Filter(new Uint8Array(addressEncoder.encode(escrow))),
                    encoding: "base58",
                },
            },
        ],
    })
        .send();
    const pendingDecoder = getPendingSettlementDecoder();
    return results.map((r) => ({
        address: r.pubkey,
        account: convertPendingSettlement(pendingDecoder.decode(decodeBase64AccountData(r.account.data))),
    }));
}
